local R=dofile('tests/kernel_npcs_harness.lua')
local n=0
local function case(name,fn,native)R.menuCase(name,fn,native);n=n+1 end
case('root parent',function(r)r.menu.openNpcsMenu();assert(r.last.menu=='forge_core_server_settings'and #r.last.options==5)end)
case('settings parent route',function(r)r.menu.openServerSettingsMenu();r.select(11);assert(r.last.id=='forge_core_npcs')end)
case('fetch refused',function(r)r.rpcHook=function()return false,'invalid_player'end;r.menu.openNpcsMenu()end)
case('fetch malformed',function(r)r.rpcHook=function()return true,false end;r.menu.openNpcsMenu()end)
case('create group cancel',function(r)r.menu.openNpcsMenu();r.select(1)end)
case('create group save',function(r)r.inputs={{'New','Desc'}};r.menu.openNpcsMenu();r.select(1);r.runTimers()end)
case('create group failed',function(r)r.inputs={{'New'}};r.menu.openNpcsMenu();r.rpcHook=function()return false,'no_permission'end;r.select(1);r.runTimers()end)
case('debug toggle',function(r)r.menu.openNpcsMenu();r.select(2);assert(r.npcs.debugIds)end)
case('group count/actions',function(r)r.menu.openNpcsGroup('1','Fallback');assert(r.last.title=='Group A'and #r.last.options==5 and r.last.options[3].disabled)end)
case('empty group',function(r)r.menu.openNpcsGroup(2,'Empty');assert(not r.last.options[3].disabled)end)
case('rename cancel',function(r)r.menu.openNpcsGroup(1,'A');r.select(2)end)
case('rename save',function(r)r.inputs={{'New','Desc'}};r.menu.openNpcsGroup(1,'A');r.select(2);r.runTimers()end)
case('delete group confirm',function(r)r.alerts={'confirm'};r.menu.openNpcsGroup(2,'B');r.select(3);r.runTimers()end)
case('delete group cancel',function(r)r.alerts={'cancel'};r.menu.openNpcsGroup(2,'B');r.select(3)end)
case('catalog page excludes animals',function(r)r.menu.openNpcsGroup(1,'A');r.select(1);assert(r.last.id=='forge_core_npcs_models'and #r.last.options==62);for _,o in ipairs(r.last.options)do assert(not(o.description or''):match('^a_c_'))end end)
case('catalog next previous',function(r)r.menu.openNpcsGroup(1,'A');r.select(1);r.select(#r.last.options);assert(#r.last.options==63);r.select(2);assert(#r.last.options==62)end)
case('search no results',function(r)r.inputs={{'not_a_model_zz'}};r.menu.openNpcsGroup(1,'A');r.select(1);r.select(1);assert(#r.last.options==1)end)
case('search exact model',function(r)r.inputs={{'a_m_m_business_01'}};r.menu.openNpcsGroup(1,'A');r.select(1);r.select(1);assert(#r.last.options==2 and r.last.options[2].description=='a_m_m_business_01')end)
case('search cancelled',function(r)r.menu.openNpcsGroup(1,'A');r.select(1);r.select(1);assert(r.last.id=='forge_core_npcs_group')end)
case('model selection cancel',function(r)r.menu.openNpcsGroup(1,'A');r.select(1);r.select(2);assert(r.last.id=='forge_core_npcs_models')end)
case('model placement confirm',function(r)r.inputs={{'N','D'}};r.menu.openNpcsGroup(1,'A');r.select(1);r.select(2);r.finish({x=1,y=2,z=3,heading=4});r.runTimers()end)
case('model placement cancelled',function(r)r.inputs={{'N','D'}};r.menu.openNpcsGroup(1,'A');r.select(1);r.select(2);r.finish(nil)end)
case('model placement refused',function(r)r.placeFailed=true;r.inputs={{'N','D'}};r.menu.openNpcsGroup(1,'A');r.select(1);r.select(2)end)
case('missing NPC',function(r)r.menu.openNpcActions(999);assert(r.last.id=='forge_core_npcs')end)
case('actions back exit',function(r)r.menu.openNpcActions(1);assert(#r.last.options==6 and r.last.menu=='forge_core_npcs_group');r.last.onBack();r.last.onExit()end)
case('group back exit',function(r)r.menu.openNpcsGroup(1,'A');r.last.onBack();r.last.onExit()end)
case('edit position',function(r)r.menu.openNpcActions(1);r.select(1);r.finish({x=1,y=2,z=3,heading=4})end)
case('edit basic cancel',function(r)r.menu.openNpcActions(1);r.select(2)end)
case('edit basic save',function(r)r.inputs={{'N','D','false'}};r.menu.openNpcActions(1);r.select(2);r.runTimers()end)
case('edit basic refused',function(r)r.inputs={{'N','D','true'}};r.menu.openNpcActions(1);r.rpcHook=function()return false,'no_permission'end;r.select(2);r.runTimers()end)
case('interaction cancel local groups',function(r)r.menu.openNpcActions(1);r.select(3)end)
case('interaction save',function(r)r.inputs={{'both','Talk','/cmd',3,'police',2,'ballas',1}};r.menu.openNpcActions(1);r.select(3);r.runTimers()end)
case('interaction catalog unavailable',function(r)r.notReady=true;r.menu.openNpcActions(1);r.select(3)end)
case('interaction catalog throws',function(r)r.groupError=true;r.menu.openNpcActions(1);r.select(3)end)
case('interaction existing unknown group kept',function(r)r.npcs.get(1).interaction.access={job='unknown',gang='other'};r.menu.openNpcActions(1);r.select(3)end)
case('animation cancel',function(r)r.menu.openNpcActions(1);r.select(4)end)
for _,preset in ipairs({'none','manual','stand_guard','cop_idle','unknown'})do case('animation '..preset,function(r)r.inputs={{preset,'CUSTOM','DICT','NAME'}};r.menu.openNpcActions(1);r.select(4);r.runTimers()end)end
case('animation preselected scenario',function(r)r.npcs.get(1).animation={scenario='WORLD_HUMAN_GUARD_STAND'};r.menu.openNpcActions(1);r.select(4)end)
case('animation preselected dictionary',function(r)r.npcs.get(1).animation={animDict='amb@world_human_cop_idles@male@idle_b',animName='idle_e'};r.menu.openNpcActions(1);r.select(4)end)
case('teleport',function(r)r.menu.openNpcActions(1);r.select(5);assert(r.positions[11].x==1)end)
case('delete NPC confirm',function(r)r.alerts={'confirm'};r.menu.openNpcActions(1);r.select(6);r.runTimers()end)
case('delete NPC cancel',function(r)r.alerts={'cancel'};r.menu.openNpcActions(1);r.select(6)end)
case('ped image optional',function(r)r.library.fivem.blips=nil;r.menu.openNpcsGroup(1,'A');assert(not r.last.options[5].image)end)
case('PR command',function(r)assert(r.commands[1].name=='npcspawner');r.commands[1].handler()end)
case('native command',function(r)assert(r.commands[1].restricted==false);r.commands[1].handler()end,true)
print('PASS NPC menu differentials '..n)
